type Question = { question: string; options: string[]; answer: number; answerRaw?: string; explanation: string };
function isCorrectOption(question: Question, optionKey: string, optionText: string): boolean {
 const raw = String(question.answerRaw ?? "").trim();
 const key = optionKey.trim().toUpperCase();
 const normalize = (value: string) => value.trim().toLowerCase().replace(/\s+/g, " ").replace(/[.。]+$/, "");
 if (raw) {
  const normalized = normalize(raw);
  if (normalized === key.toLowerCase() || normalized === ("option " + key).toLowerCase() || normalized === (key + ".").toLowerCase()) return true;
  if (/^[1-4]$/.test(normalized) && Number(normalized) === key.charCodeAt(0) - 64) return true;
  if (normalize(optionText) === normalized) return true;
 }
 return question.answer === key.charCodeAt(0) - 65;
}
